-- Initial OpsFlow PostgreSQL schema.
-- Do not edit this migration after it has been applied to a database.
CREATE TABLE users (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    full_name VARCHAR(255) NOT NULL,
    email VARCHAR(255) NOT NULL UNIQUE,
    password VARCHAR(255) NOT NULL,
    role VARCHAR(50) NOT NULL,
    active BOOLEAN NOT NULL DEFAULT TRUE,
    created_at TIMESTAMP WITHOUT TIME ZONE
);

CREATE TABLE requests (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    title VARCHAR(255) NOT NULL,
    description TEXT,
    priority VARCHAR(255) NOT NULL,
    status VARCHAR(255) NOT NULL DEFAULT 'OPEN',
    created_at TIMESTAMP WITHOUT TIME ZONE NOT NULL,
    user_id BIGINT NOT NULL,
    assigned_to BIGINT,
    CONSTRAINT fk_requests_user FOREIGN KEY (user_id) REFERENCES users (id),
    CONSTRAINT fk_requests_assigned_to FOREIGN KEY (assigned_to) REFERENCES users (id)
);

CREATE INDEX idx_requests_user_id ON requests (user_id);
CREATE INDEX idx_requests_assigned_to ON requests (assigned_to);
CREATE INDEX idx_requests_status ON requests (status);
